      formula: "ρ = m/V",
      steps: [
        "Write ρ = m/V.",
        "Substitute: ρ = 900/1.5.",
        "Calculate: ρ = 600 g/cm³."
      ],
      ans: "600 g/cm³",
      final_check: "600 × 1.5 = 900 g.",
      common_mistakes: ["Reversing mass and volume.", "Rounding before completing the calculation."],
